<?php ob_start(); ?><div class="section-head"><div><p class="eyebrow">Administration</p><h1><?= e($heading) ?></h1></div><?php if (!empty($newUrl)): ?><a class="button" href="<?= e(url($newUrl)) ?>">Add new</a><?php endif; ?></div><div class="table-wrap"><table><thead><tr><?php foreach ($columns as $label): ?><th><?= e($label) ?></th><?php endforeach; ?><th>Actions</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><?php foreach (array_keys($columns) as $key): ?><td><?= e((string)($row[$key] ?? '')) ?></td><?php endforeach; ?><td><?php if (!empty($editBase)): ?><a href="<?= e(url($editBase.'/'.$row['id'])) ?>">Edit</a><?php endif; ?><?php if (!empty($statusBase)): ?> · <form style="display:inline" method="post" action="<?= e(url($statusBase.'/'.$row['id'])) ?>"><?= csrf_field() ?><select name="status" onchange="this.form.submit()"><?php foreach ($statuses as $status): ?><option <?= ($row['status']??'')===$status?'selected':'' ?>><?= e($status) ?></option><?php endforeach; ?></select></form><?php endif; ?><?php if (!empty($deleteBase)): ?> · <form style="display:inline" method="post" action="<?= e(url($deleteBase.'/'.$row['id'])) ?>"><?= csrf_field() ?><button class="button ghost" data-confirm="Delete this item permanently?">Delete</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php if (!$rows): ?><div class="empty">No records yet.</div><?php endif; ?></div><?php $adminContent=ob_get_clean(); require ROOT.'/app/views/admin/shell.php'; ?>

